import{_ as n,a0 as u,w as a,s,ao as I,I as i,x as p,a1 as e,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const c=JSON.parse('{"title":"戴文的Linux內核專題：11 配置內核(7) | LCTT x X-CMD","titleTemplate":false,"description":"戴文的Linux內核專題：11 配置內核(7) | LCTT (The Linux Kernel) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"戴文的Linux內核專題：11 配置內核(7) | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"戴文的Linux內核專題：11 配置內核(7) | LCTT (The Linux Kernel) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The Linux Kernel/11 The Linux Kernel--Configuring the Kernel Part 7","title":"戴文的Linux內核專題：11 配置內核(7)","tag":"The Linux Kernel","desc":""},"relativePath":"The Linux Kernel/11 The Linux Kernel--Configuring the Kernel Part 7.md","filePath":"[post].md"}'),P={name:"The Linux Kernel/11 The Linux Kernel--Configuring the Kernel Part 7.md"};function l(C,t,d,T,g,m){const o=u("Link");return a(),s("div",null,[t[11]||(t[11]=I('<h1 id="戴文的linux內核專題-11-配置內核-7" tabindex="-1">戴文的Linux內核專題：11 配置內核(7) <a class="header-anchor" href="#戴文的linux內核專題-11-配置內核-7" aria-label="Permalink to “戴文的Linux內核專題：11 配置內核(7)”">​</a></h1><p><img src="http://www.linux.org/attachments/slide-jpeg.474/" alt=""></p><p>來享受這個Linux內核系列的下一篇文章。我們將繼續配置PCI特性，接着是計算機中最重要的特性-網絡。</p><p>進程地址空間標識符(Process Address Space Identifiers (PASIDs))允許PCI設備同時訪問多個IO地址空間(PCI PASID support)。這個特性需要一個支持PASIDs支持的IOMMU。</p><p>下面我們可以啓用/禁用&quot;PCI IO-APIC hotplug support&quot;。APIC代表高級可編程中斷控制器(Advanced Programmable Interrupt Controllers)。可編程中斷控制器(PIC)收集所有來自不同源發給一個或者多個CPU流水線的中斷。高級PIC與PIC一樣，但是它們有更多的特性像高級中斷管理和更多的優先級模型。熱插拔是一種在系統在運行時加入一件設備的能力並且不需要重啓。這個驅動是為了PCI主板能擁有處理輸入/輸出APIC熱插拔的能力。</p><p>在這之後，下面的問題詢問的是啓用&quot;ISA-style DMA support&quot;。在前文中提到過，DMA是直接內存訪問，它是一種設備無需藉助CPU直接訪問內存的能力。ISA代表的是工業標準架構(Industry Standard Architecture),它是一種像PCI的總線標準。這個特性允許在ISA主板上支持DMA。</p><p>現在，我們可以移步到&quot;PC Card (PCMCIA/CardBus) support&quot;。PCMCIA代表的是個人計算機存儲卡國際協會(Personal Computer Memory Card International Association)。PC卡、PCMCIA卡和Cardbus卡都是卡片形狀的筆記本外設。</p><p>下一個PCMCIA選項處理&quot;16-bit PCMCIA support&quot;。一些舊的計算機使用16位PCMCIA卡。</p><p>為了從用户空間加載卡式信息結構(Card Information Structure (CIS))以使PCMCIA卡正常工作，這個特性應該啓用(Load CIS updates from userspace)。</p><p>CardBus是16位PCMCIA的更新32位版本。這個驅動提供對這類設備的支持(32-bit CardBus support)。為了使用32位PC卡，需要一個兼容Cardbus的主機橋。</p><p>下面的驅動提供對上面提到的CardBus橋支持(CardBus yenta-compatible bridge support)。這是PCMCIA卡插入的硬件端口。</p><p>下面三個選項&quot;Special initialization for O2Micro bridges&quot;、&quot;Special initialization for Ricoh bridges&quot;和&quot;Special initialization for TI and EnE bridges&quot;。它們都是不同類型卡橋。</p><p>接下來，提供了&quot;Auto-tune EnE bridges for CB cards&quot;的驅動。</p><p>&quot;Special initialization for Toshiba ToPIC bridges&quot;可以在下一個選項中啓用/關閉。</p><p>下一個提供的設備驅動是&quot;Cirrus PD6729 compatible bridge support&quot;。這在一些老的筆記本上需要。</p><p>下一個PCMCIA橋驅動是Itel的&quot;i82092 compatible bridge support&quot;。這也在一些老的筆記本上出現。這是另外一種橋驅動。</p><p>在這之後，以下的選項詢問關於是否啓用&quot;Support for PCI Hotplug&quot;。</p><p>下一步，ACPI PCI熱插拔可以啓用(ACPI PCI Hotplug driver)。這個驅動允許擁有ACPI的PCI設備熱插拔(這個特性之前已經討論過)。</p><p>對於IBM系統，為了ACPI熱插拔下一個驅動應該啓用(ACPI PCI Hotplug driver IBM extensions)。這就像上面的特性但特定與IBM設備。</p><p>對於帶有支持CompactPCI熱插拔支持的CompactPCI卡的系統，啓用&quot;CompactPCI Hotplug driver&quot;。</p><p>下面，我們有一個選項對於另一種CompactPCI系統卡(Ziatech ZT5550 CompactPCI Hotplug)。</p><p>使用#ENUM熱插拔信號通過標準IO口作為系統註冊位的CompactPCI卡需要這個驅動(Generic port I/O CompactPCI Hotplug)。</p><p>使用SHPC PCI熱插拔控制器的主板需要下一個驅動(SHPC PCI Hotplug driver)。SHPC代表的是標準熱插拔控制器(Standard Hot-Plug Controller)。這對於PCI主板是一個通用熱插拔系統。</p><p>RapidIO互聯設備也需要一個特殊的驅動(RapidIO support)。RapidIO芯片和主板快於PCI和PCIe。</p><p>&quot;IDT Tsi721 PCI Express SRIO Controller&quot;是一個特殊類型的RapidIO控制器。</p><p>下一個選項允許開發者輸入在主機完成枚舉前系統發現節點應該等待多久時間(以秒計)。這通常選擇默認值</p><p>下一個特性會允許RapidIO系統接受除了維護信號外其他流量(Enable RapidIO Input/Output Ports)。</p><p>為了使用DMA引擎框架從RIO設備上發送或接收RapidIO數據，啓用這個驅動(DMA Engine support for RapidIO)。RIO設備是可重配的輸入/輸出設備。RapidIO使用NREAD和NWRITE請求來在本地和遠程內存間傳輸數據，因此驅動需要允許RapidIO使用DMA訪問RIO設備。DMA控制器需要在內存中完成這個特性。</p><p>如果允許，RapidIO可以提供調試信息(RapidIO subsystem debug messages)。如前面所説，調試特性可以禁用，除非你或者其他人使用的內核需要調試特性。</p><p>下一個驅動提供&quot;IDT Tsi57x SRIO switches support&quot;。這是一組串口RapidIO開關，下面的四個選項是對於不同串口RapisIO開關驅動-&quot;IDT CPS-xx SRIO switches support&quot;、&quot;Tsi568 SRIO switch support&quot;、&quot;IDT CPS Gen.2 SRIO switch support&quot;和&quot;Tsi500 Parallel RapidIO switch support&quot;。</p><p>管理這些驅動後，我們可以繼續其他的內核選項。下一個選項提供對ELF的支持(Kernel support for ELF binaries)。可執行與可鏈接格式(Executable and Linkable Format (ELF))支持是一種可執行文件規範。強烈建議啓動這個。</p><p>為了執行那些需要解釋器的腳本和二進制文件，這個特性必須啓用(Kernel support for MISC binaries)。這些可執行文件的類型通常稱為包裝器驅動的二進制格式。例如包括Python2/3、 .NET、Java、DOS執行程序等等。</p><p>當這個選項啓用時(Enable core dump support)，內核可以生成崩潰文件。這是一個調試特性。除非這個內核是用來調試(無論內核本身還是軟件)，不然這個並不必要。</p><p>64位處理器可以執行32位程序如果啓用了&quot;IA32 Emulation&quot;。最好啓用這個特性除非開發者確定內核永遠不會運行32位代碼。</p><p>老式的a.out二進制文件也被支持(IA32 a.out support)。就像它稱呼的那樣，&quot;彙編輸出&quot;(Assembler Output),這是一種已編譯代碼的文件格式。</p><p>下一個設置允許32位處理器訪問完整的64位寄存器文件和寬數據路徑(x32 ABI for 64-bit mode)。然而，仍舊使用32位指針。這些32位進程將比同樣的為64位編譯的進程使用內存更少，因為他們使用32位指針</p><p>下面，我們將講網絡支持。</p><p>我們第一個網絡設定是啓用一般的網絡(Networking Support)。很少有開發者會禁用這個特性。如果他們這麼做了，內核會變得又小又快，但是它將無法使用Wifi、藍牙、以太網或者任何由網絡設備或協議處理的連接。一些在獨立系統上程序也需要這個特性，即使硬件上不存在網絡設備。舉例來説，X11依賴於網絡特性。如果你能提供一個替代方案在屏幕上顯示圖形，你才能在內核中禁用網絡特性。</p><p>&quot;Packet socket&quot;允許在沒有中介物的情況下，進程與網絡設備間進行通信。這個增強了性能。</p><p>ss工具需要啓用這個特性用來數據包監控(Packet: sockets monitoring interface)。包監控意味着監視相關本地設備的網絡流量。</p><p>&quot;Unix domain sockets&quot; (Unix域套接字)是用來建立和訪問網絡連接。X窗口系統需要這個特性；這是一個極好的例子來説明為什麼即使系統中不會使用網絡但是仍然在內核中啓用網絡特性。Unix域套接字是運行在同一台機器上的進程間的網絡協議。</p><p>上面的Unix套接字可以被ss工具監控，但是下面一個特性必須先啓用(UNIX: socket monitoring interface)。</p><p>轉換(Transformation (XFRM))用户配置接口被許多Linux原生工具用到，所以這個特性強烈建議啓用(Transformation user configuration)。這個會啓用Ipsec-Internet Protocol SECurity(互聯網協議安全)。Ipsec控制着驗證並且/或者加密IP數據包。</p><p>下一個特性允許開發者給予網絡數據包第二個政策(稱作sub-policy)(Transformation sub policy support)。</p><p>IPsec安全聯合定位器可以當這個特性啓用時(Transformation migrate database)動態更新。使用移動IPv6的設備需要這個特性。當計算機與路由器或者任何形式的網絡設備設置了一個網絡連接，安全協議會確保兩者不會意外地連接到網絡上的其他設備上。IP數據包被設定發送到一個特定的設備上。然而，移動設備會使用不同的網絡，比如説提供了4G信號，也需要能夠使用相同的連接到新的網絡點上。即使可能是相同的4G供應商，不同的設備會提供一個4G連接到它的物理位置。當設備處在新的區域時，它仍會使用相同的IP地址。</p><p>下一個特性是顯示在包處理中的傳輸錯誤統計(Transformation statistics)。這對開發者有用。如果不需要，可以禁用掉它。</p><p>&quot;PF_KEY sockets&quot;與KAME套接字兼容且它在使用從KAME移植來的IPsec工具時有用。KAME是IPv4 IPsec、IPv6 IPsec和IPv6的免費協議棧。</p><p>這是另外一個需要的移動IPv6特性，它增加了到PF_KEYv2套接字的PF_KEY MIGRATE消息(PF_KEY MIGRATE)。</p><p>下面的是最重要的並且是在網絡中最著名的需要啓用的特性-&quot;TCP/IP networking&quot;。大多數網絡(包括因特網)依賴於這個協議。甚至X窗口系統也使用TCP/IP。這個特性甚至允許用户ping它們自己(命令：ping 127.0.0.1)。要使用因特網或者X11，這個必須啓用。</p><p>為了尋找網絡中數個計算機，&quot;IP: multicasting&quot;必須啓用。多播是一種給多台計算機但不是全部計算機發送消息的能力。廣播會給網絡中的所有計算機發送信號。</p><p>如果這是一個路由器Linux系統的內核,那就啓用這個選項(IP: advanced router)。</p><p>如果下面的特性啓用了，那麼IP地址會在啓動時自動配置(IP: kernel level autoconfiguration)。當用户希望不用配置就能連接到一個網絡時是很有用的。</p><p>啓用了DHCP協議支持，那麼Linux系統可以通過網絡像NFS掛載它的根文件系統並且使用DHCP發現IP地址(IP: DHCP support)。這允許Linux系統通過網絡擁有它的遠程根文件系統而不必用户在每次系統啓動時手動管理進程。</p><p>下面的選項和上面的類似除了使用的是BOOTP而不是DHCP(IP: BOOTP support。BOOTP是自舉協議；這個協議使用UDP而不是TCP並且只能使用IPv4網絡</p><p>RARP是一個被BOOTP和DHCP替代了的舊協議，但是它仍可以加到內核中(IP: RARP support)。</p><p>網絡協議可以在另一個概念中使用，稱作&quot;隧道&quot;。這個特性可以用在Linux內核中(IP: tunneling)。安全shell協議(The secure shell protocol (SSH))就是隧道協議的一個例子。SSH需要這個特性。</p><p>下面的驅動可以多路複用通用路由封裝包(GRE (Generic Routing Encapsulation))(IP: GRE demultiplexer)。多路複用是一個使單個信號進入不同部分的過程(這不會複製消息，只是分解它)。GRE是一種隧道協議。</p><p>下面的特性允許GRE通道在IP連接中形成(IP: GRE tunnels over IP)。這允許GRE隧道在IP網絡中形成。</p><p>當啓用這個特性(IP: broadcast GRE over IP)，廣播可以通過IP使用GRE。</p><p>在Linux系統的路由器內，為了讓IP包發往多個地址，需要啓用這個(IP: multicast routing)。</p><hr>',61)),i("p",null,[t[1]||(t[1]=p("via: ",-1)),e(o,{href:"http://www.linux.org/threads/the-linux-kernel-configuring-the-kernel-part-7.4490/"},{default:r(()=>[...t[0]||(t[0]=[p("http://www.linux.org/threads/the-linux-kernel-configuring-the-kernel-part-7.4490/",-1)])]),_:1})]),i("p",null,[t[4]||(t[4]=p("譯者：",-1)),e(o,{href:"https://github.com/geekpi"},{default:r(()=>[...t[2]||(t[2]=[p("geekpi",-1)])]),_:1}),t[5]||(t[5]=p(" 校對：",-1)),e(o,{href:"https://github.com/wxy"},{default:r(()=>[...t[3]||(t[3]=[p("wxy",-1)])]),_:1})]),i("p",null,[t[8]||(t[8]=p("本文由 ",-1)),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[6]||(t[6]=[p("LCTT",-1)])]),_:1}),t[9]||(t[9]=p(" 原創翻譯，",-1)),e(o,{href:"http://linux.cn/"},{default:r(()=>[...t[7]||(t[7]=[p("Linux中國",-1)])]),_:1}),t[10]||(t[10]=p(" 榮譽推出",-1))])])}const A=n(P,[["render",l]]);export{c as __pageData,A as default};
